public class Main {
    static int doubled(int n) {
        try {
            System.out.println("try " + n);
            if (n > 0) {
                return n * 2;
            }
            return -1;
        } finally {
            System.out.println("finally " + n);
            n = 99;
        }
    }

    public static void main(String[] args) {
        System.out.println("got " + doubled(3));
        System.out.println("---");
        System.out.println("got " + doubled(0));
    }
}
